\label{equivalancethm3point1}
Let $F=\{f_i\}_{i=1}^N$ be a frame for $\mathcal{H}_n$ and let $A \in \mathbb{C}^{k\times N}$ have full row rank, with row vectors $\{a_i\}_{i=1}^k$. Then the following are equivalent:
\begin{enumerate}
    \item $F$ has the vanishing $A$-moment dilation property.

    \item $F$ has a dual frame $G=\{g_i\}_{i=1}^N$ such that $G$ has vanishing $A$-moment.

    \item $\mathrm{Row}(A) \cap \mathrm{Ran}(\Theta_F) = \{0\}$.

    \item The family $\{P^\perp a_i\}_{i=1}^k$ is linearly independent, where $P$ is the orthogonal projection onto $\mathrm{Ran}(\Theta_F)$.

    \item 
     $X \preceq Y$. 

\end{enumerate}

\label{lem3point5}
Let $V$ be a finite-dimensional affine space over $\mathbb{R}$ or $\mathbb{C}$, and let $Z_1,\dots,Z_m \subsetneq V$
be proper algebraic subsets. Then $Z_1\cup Z_2\cup\cdots\cup Z_m \neq V.$

\cite{sali}\label{cor3point7}
Let $F=\{f_i\}_{i=1}^{N}$ be a sequence in a Hilbert space $\mathcal H_n$. Then there exists a partition $\{\Lambda_j\}_{j=1}^{J}$ of $\{1,2,\ldots,N\}$, unique up to permutations, such that

\begin{enumerate}
    \item Each subsequence $F_j:=\{f_i\}_{i\in\Lambda_j}$  is linearly connected;

    \item If $ H_j=\operatorname{span}\{f_i:\, i\in\Lambda_j\},$ then
$\mathcal{H}_n = H_1\oplus H_2\oplus\cdots\oplus H_J .$
\end{enumerate}
